INSERT INTO battery_types (id, title, capacity_mah, voltage_v, photo, video, short_description, description, is_deleted) VALUES
  (1, 'Li-ion (литий-ионный)', 3000, 3.7, 'li_ion.jpg', 'li_ion.mp4', 'Высокая удельная энергия, малый саморазряд', 'Литий-ионные аккумуляторы широко применяются в смартфонах, ноутбуках, электротранспорте. Характеризуются высокой плотностью энергии, отсутствием эффекта памяти. Номинальное напряжение одной ячейки обычно 3,6–3,7 В.', false),
  (2, 'Li-Po (литий-полимерный)', 1500, 3.7, 'li_po.jpg', 'li_po.mp4', 'Гибкая форма, малый вес, высокая токоотдача', 'Литий-полимерные аккумуляторы позволяют делать батареи тонкими и гибкими. Часто применяются в дронах, носимой электронике. По удельной энергии и напряжению близки к Li-ion.', false),
  (3, 'Ni-MH (никель-металлгидридный)', 2500, 1.2, 'ni_mh.jpg', 'ni_mh.mp4', 'Экологичность, перезаряжаемость, стабильность при низких температурах', 'Никель-металлгидридные аккумуляторы — перезаряжаемая альтернатива без кадмия. Номинальное напряжение элемента 1,2 В. Используются в бытовой технике, гибридном транспорте.', false),
  (4, 'Аккумулятор LiFePO4', 3200, 3.2, 'Li_fe_po.jpg', 'Li_fe_po.mp4', 'Долгий срок службы, безопасность, стабильное напряжение 3,2 В', 'Литий-железо-фосфатные (LiFePO4) аккумуляторы отличаются высокой термостабильностью, большим числом циклов заряда-разряда и отсутствием риска возгорания. Номинальное напряжение ячейки 3,2 В. Широко применяются в накопителях энергии, электровелосипедах и силовом оборудовании.', false)
